contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint contractBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint contractBalanceAfterDeposit = address(c).balance;
        uint testBalanceAfterDeposit = address(this).balance;

        bool withdrawReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint contractBalanceAfterWithdraw = address(c).balance;
        uint testBalanceAfterWithdraw = address(this).balance;

        bool depositOk = (contractBalanceAfterDeposit == contractBalanceBefore + amount) &&
                         (testBalanceAfterDeposit + amount == testBalanceBefore);

        bool withdrawOk = withdrawReverted
            ? (contractBalanceAfterWithdraw == contractBalanceAfterDeposit &&
               testBalanceAfterWithdraw == testBalanceAfterDeposit)
            : (contractBalanceAfterWithdraw == contractBalanceBefore &&
               testBalanceAfterWithdraw == testBalanceBefore);

        assert(depositOk && withdrawOk);
    }

    receive() external payable {}
}

