// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint contractBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint contractBalanceAfterDeposit = address(c).balance;
        uint testBalanceAfterDeposit = address(this).balance;
        bool withdrawReverted;
        try c.withdrawAll() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint contractBalanceAfterWithdraw = address(c).balance;
        uint testBalanceAfterWithdraw = address(this).balance;
        bool depositOk = (contractBalanceAfterDeposit == contractBalanceBefore + amount) &&
                         (testBalanceAfterDeposit + amount == testBalanceBefore);
        bool withdrawOk = withdrawReverted
            ? (contractBalanceAfterWithdraw == contractBalanceAfterDeposit &&
               testBalanceAfterWithdraw == testBalanceAfterDeposit)
            : (contractBalanceAfterWithdraw == contractBalanceBefore &&
               testBalanceAfterWithdraw == testBalanceBefore);
        assertTrue(depositOk && withdrawOk);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
